async function previewAccountAction(account,action){if(!authorized||mode!=='real'||configBusy||!auth?.currentUser)return;clearAccountPlan();const generation=epoch,revision=++configRevision,user=auth.currentUser;configBusy=true;configControls();$('config-status').textContent='Preparando vista previa para '+accountActionLabels[action]+'; todavía no se ejecuta la acción…';try{const plan=await configRequest('/api/admin/users/action/preview',{method:'POST',headers:{'Content-Type':'application/json','X-Requested-With':'XmlHttpRequest'},body:JSON.stringify({uid:account.uid,action})},generation,revision,user);if(!plan)return;if(plan.uid!==account.uid||plan.action!==action||typeof plan.planId!=='string'||!plan.planId||typeof plan.blocked!=='boolean')throw Error('invalid-plan');accountPlan=plan;renderAccountPlan(account,plan);$('config-status').textContent=plan.blocked?'El backend bloqueó la acción. Revisa los motivos.':'Vista previa lista. Comprueba la identidad, el alcance y confirma el UID para ejecutar.';}catch(error){if(configValid(generation,revision,user)){clearAccountPlan();configFailure(error);}}finally{if(generation===epoch&&revision===configRevision){configBusy=false;configControls();}}}
