$('config-load').addEventListener('click',()=>loadConfig());$('config-next').addEventListener('click',()=>loadConfig(true));
if(typeof setInterval==='function')setInterval(()=>{if(authorized&&auth?.currentUser&&!document.hidden&&mode==='real'&&!busy&&$('auto-refresh').checked)load();},60000);
$('refresh').addEventListener('click',load);$('mode').addEventListener('change',()=>{scopeNavigation++;mode=$('mode').value;render();});for(const id of ['service-filter','state-filter','operation-filter'])$(id).addEventListener(id==='operation-filter'?'input':'change',history);for(const [id,delta]of [['zoom-in',.15],['zoom-out',-.15]])$(id).addEventListener('click',()=>{zoom=Math.max(.55,Math.min(1.9,zoom+delta));render();});
try{auth=firebase.auth();auth.onAuthStateChanged(user=>{epoch++;busy=false;clear();$('signin').disabled=false;$('signout').hidden=!user;$('access-message').textContent=user?'Validando administrador…':'Inicia sesión con una cuenta administradora autorizada.';if(user)load();});$('signin').addEventListener('click',()=>{const provider=new firebase.auth.GoogleAuthProvider();provider.setCustomParameters({prompt:'select_account'});auth.signInWithPopup(provider).catch(()=>{$('access-message').textContent='No se pudo iniciar sesión.';});});$('signout').addEventListener('click',()=>auth.signOut().catch(()=>{$('access-message').textContent='No se pudo cerrar sesión.';}));}catch(_){$('access-message').textContent='No se pudo cargar la autenticación.';}
